-- Datos de la seccion Editorial: catalogo de obras y reparto de copyright.
-- Generado por herramientas/umpg/umpg_obras.py a partir de los CSV de UMPG Window.
-- Idempotente: los ids son deterministas y hay upsert, se puede reejecutar.
-- Requiere supabase/editorial.sql aplicado antes.

begin;

-- ── obras (157)
on conflict (work_code) do update set
  titulo = excluded.titulo,
  iswc = coalesce(excluded.iswc, public.obras.iswc),
  recorded_by = coalesce(excluded.recorded_by, public.obras.recorded_by);

-- ── obra_participantes (736)
delete from public.obra_participantes where obra_id in (select id from public.obras);
on conflict (id) do nothing;

commit;

-- comprobacion
select 'obras' as tabla, count(*) from public.obras
union all select 'obra_participantes', count(*) from public.obra_participantes
union all select 'con cliente_id', count(*) from public.obra_participantes where cliente_id is not null;
